local config = {
  ui_story_5063_50630101_1_dialog_content = "(Ugh... My head.)",
  ui_story_5063_50630101_2_dialog_content = "(I must be more tired than I thought, to suddenly fall asleep outside like this.)",
  ui_story_5063_50630101_3_dialog_content = "(Thank goodness I woke up just now. I should still have enough time to make my next meeting.)",
  ui_story_5063_50630101_4_dialog_content = "Hold on, please!",
  ui_story_5063_50630101_5_dialog_content = "Hmm?",
  ui_story_5063_50630101_6_dialog_content = "Right now, the Hall of Justice is in closed session. Unauthorized individuals are not allowed inside.",
  ui_story_5063_50630101_7_dialog_content = "Are you guards new, by any chance?",
  ui_story_5063_50630101_8_dialog_content = "I happen to be the Chief Judge here in the Hall of Justice.",
  ui_story_5063_50630101_9_dialog_content = "I'm hosting a very important meeting scheduled to start momentarily. Please let me through so that I can begin preparations.",
  ui_story_5063_50630101_10_dialog_content = "You're <color=#FFB400>dressed as a knight</color>, yet you have the audacity to impersonate the esteemed Chief Judge in this hallowed ground?",
  ui_story_5063_50630101_11_dialog_content = "A person with such devious intentions—how can we allow you to deceive your way through?!",
  ui_story_5063_50630101_12_dialog_content = "I truly admire your dedication and sincerity, but I truly am the Chief Judge of Lumopolis! If you still don't believe me...",
  ui_story_5063_50630101_13_dialog_content = "You're not giving up on this, huh? It seems we'll have to detain you for a thorough investigation!",
  ui_story_5063_50630101_14_dialog_content = "What did you say to me?",
  ui_story_5063_50630101_15_dialog_content = "Stop right there!!!",
  ui_story_5063_50630102_1_dialog_content = "(Why don't any of these guards recognize me?)",
  ui_story_5063_50630102_2_dialog_content = "(Also... When did I change into this knight uniform? I don't recall doing so at all!)",
  ui_story_5063_50630102_3_dialog_content = "Stop! Don't you dare run!",
  ui_story_5063_50630102_4_dialog_content = "...",
  ui_story_5063_50630102_5_dialog_content = "This is bad. She's about to barge into the Hall of Justice!",
  ui_story_5063_50630102_6_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5063_50630102_7_dialog_content = "So bright... What's that thing?",
  ui_story_5063_50630102_8_dialog_content = "Our apologies, Chief Judge!",
  ui_story_5063_50630102_9_dialog_content = "(Do they... finally recognize me?)",
  ui_story_5063_50630102_10_dialog_content = "Chief Judge, we deeply apologize for startling you! We'll take this devious impersonator into custody right away!",
  ui_story_5063_50630102_11_dialog_content = "(The guards... They don't seem to be speaking to me.)",
  ui_story_5063_50630102_12_dialog_content = "Thank you all for your assistance.",
  ui_story_5063_50630102_13_dialog_content = "This here's a fresh Justice Knight at the Hall of Justice, so she's probably not familiar with the rules here.",
  ui_story_5063_50630102_14_dialog_content = "I'll make sure to guide her in how to conduct herself in the Hall of Justice. The rest of you can leave for now.",
  ui_story_5063_50630102_15_dialog_content = "Yes, Chief Judge!",
  ui_story_5063_50630102_16_dialog_content = "... <color=#FFB400>Chief Judge</color>?!",
  ui_story_5063_50630102_17_dialog_content = "But only one person can be Chief Judge... What on earth is happening?!",
  ui_story_5063_50630102_18_dialog_content = "Unauthorized entry into the Hall of Justice, you've got quite the audacity.",
  ui_story_5063_50630102_19_dialog_content = "I beg your pardon? I am Irridon, the Chief Judge of the Lumopolis Hall of Justice, and I am free to come and go as I please...",
  ui_story_5063_50630102_20_dialog_content = "Now tell me, what do you think you're doing in my seat?",
  ui_story_5063_50630102_21_dialog_content = "Having dreams is a good thing, but you need to carefully assess whether you have the ability for it.",
  ui_story_5063_50630102_22_dialog_content = "I've always appreciated young folks with aspirations, but not the ones lost in daydreams.",
  ui_story_5063_50630102_23_dialog_content = "Get a clear view of where you stand. If you want to continue serving the Hall of Justice...",
  ui_story_5063_50630102_24_dialog_content = "Starting now, do as I say, and watch as I do.",
  ui_story_5063_50630102_25_dialog_content = "\"Do as I say, and watch as I do...\" But that's <color=#FFB400>my father's favorite phrase</color>! Why do you know that?!",
  ui_story_5063_50630102_26_dialog_content = "I'm the chosen successor favored by your father, Chief Judge Rodell.",
  ui_story_5063_50630102_27_dialog_content = "Don't assume that just because your father is Chief Judge, you'll automatically become Chief Judge someday.",
  ui_story_5063_50630102_28_dialog_content = "Right now, you're just a new, ordinary Justice Knight at the Hall of Justice.",
  ui_story_5063_50630102_29_dialog_content = "I'm... nothing more than a Justice Knight?",
  ui_story_5063_50630102_30_dialog_content = "It seems you've truly been lost in some daydream; haven't you woken up yet?",
  ui_story_5063_50630102_31_dialog_content = "(A dream... It's true, I did have some strange dreams this morning, but I can't remember any of them now.)",
  ui_story_5063_50630102_32_dialog_content = "(W-Was I dreaming all along? Why did I think I was the Chief Judge just now?)",
  ui_story_5063_50630102_33_dialog_content = "(Those dreams... They must have been so realistic that I thought they were true!)",
  ui_story_5063_50630102_34_dialog_content = "(So my behavior towards those guards just now... In their eyes, I was no different than a liar!)",
  ui_story_5063_50630102_35_dialog_content = "Please forgive my unceremonious behavior, Chief Judge...",
  ui_story_5063_50630102_36_dialog_content = "Well, your attitude does seem sincere.",
  ui_story_5063_50630102_37_dialog_content = "Out of respect for your father, I'll let this slide today. Go back and reflect on your behaviors; repay me through your actions.",
  ui_story_5063_50630102_38_dialog_content = "Now, go and carry out your responsibilities now.",
  ui_story_5063_50630102_39_dialog_content = "Thank you, Chief Judge!",
  ui_story_5063_50630102_40_dialog_content = "(I can't believe I made such a terrible mistake on my very first day. How shameful.)",
  ui_story_5063_50630102_41_dialog_content = "(Thank goodness the Chief Judge was gracious enough to overlook my transgression...)",
  ui_story_5063_50630102_42_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5063_50630102_43_dialog_content = "Where's the Chief Judge?!",
  ui_story_5063_50630102_44_dialog_content = "Chief Judge!",
  ui_story_5063_50630102_45_dialog_content = "I believe you are mistaken. The Chief Judge is sitting over there.",
  ui_story_5063_50630102_46_dialog_content = "Identify yourself.",
  ui_story_5063_50630102_47_dialog_content = "Chief Judge, my family and I have been wrongly accused, and we hope that you can help us seek justice and clear our names!",
  ui_story_5063_50630102_48_dialog_content = "So, are you pronounced guilty?",
  ui_story_5063_50630102_49_dialog_content = "Every judgment rendered by the Hall of Justice is sanctioned by the God of Light, with absolutely no room for error.",
  ui_story_5063_50630102_50_dialog_content = "Being a guilty party, you refused to admit your wrongdoing and face the punishment and unlawfully barged into the Hall of Justice, desecrating our sacred judgments...",
  ui_story_5063_50630102_51_dialog_content = "You're simply heinous and deserve to be punished more!",
  ui_story_5063_50630102_52_dialog_content = "...",
  ui_story_5063_50630102_53_dialog_content = "Humph! As expected, I shouldn't have placed my hopes on Lumopolis in the first place!",
  ui_story_5063_50630102_54_dialog_content = "Sitting in the Hall of Justice and putting on airs doesn't mean you truly embody absolute justice.",
  ui_story_5063_50630102_55_dialog_content = "You'll see. I'll do justice my own way.",
  ui_story_5063_50630102_56_dialog_content = "This is outrageous!!!",
  ui_story_5063_50630102_57_dialog_content = "Justice Knight, why are you still standing there?",
  ui_story_5063_50630102_58_dialog_content = "Justice Knight Irridon, at your command!",
  ui_story_5063_50630102_59_dialog_content = "Go and arrest madwoman! Don't let me down again!",
  ui_story_5063_50630102_60_dialog_content = "Yes, Chief Judge!",
  ui_story_5063_50630201_1_dialog_content = "Hold it, stop right there!",
  ui_story_5063_50630201_2_dialog_content = "Surrender now, and you may have a chance for a lighter sentencing.",
  ui_story_5063_50630201_3_dialog_content = "Oh? Then tell me, what crime have I truly committed, and why are you arresting me?",
  ui_story_5063_50630201_4_dialog_content = "By barging into the Hall of Justice, you have disrupted the judicial process and violated the sanctity of the Hall. This is your first offense.",
  ui_story_5063_50630201_5_dialog_content = "Your second, as you so kindly pointed out yourself, is that you are a fugitive of the law.",
  ui_story_5063_50630201_6_dialog_content = "By order of the Chief Judge herself, you are hereby under arrest. The safety and security of Lumopolis and its laws must be upheld!",
  ui_story_5063_50630201_7_dialog_content = "Heh, all this talk about \"safety\" and \"laws,\" but you don't even comprehend half of it!",
  ui_story_5063_50630201_8_dialog_content = "You've never even thought about why you should obey those so-called commands...",
  ui_story_5063_50630201_9_dialog_content = "At the end of the day, you're just a hangman fed by this seemingly pristine city!",
  ui_story_5063_50630201_10_dialog_content = "You must truly be mad to insult a Justice Knight like this...!",
  ui_story_5063_50630201_11_dialog_content = "What else can I do? You wouldn't listen anyway. You don't even know me, yet you're already filled with bias...",
  ui_story_5063_50630201_12_dialog_content = "The city's no better. Hmph, even though I used to be a part of it...",
  ui_story_5063_50630201_13_dialog_content = "When the knife's not at your throat, you'll never know what it's like to be driven to a dead end by bias and arrogance!",
  ui_story_5063_50630201_14_dialog_content = "Are you willing to tell me what happened to you?",
  ui_story_5063_50630201_15_dialog_content = "Too bad, it's too late now. Heh, look, they're already here.",
  ui_story_5063_50630201_16_dialog_content = "Protection! Loyalty! Glory!",
  ui_story_5063_50630201_17_dialog_content = "Are you here to help me arrest the fugitive? If so, you're just in time—",
  ui_story_5063_50630201_18_dialog_content = "Attack!",
  ui_story_5063_50630201_19_dialog_content = "*Coughs* Wh-What are you...?",
  ui_story_5063_50630302_1_dialog_content = "What's happening? Why did those guards vanish when they were attacked? I'm so confused...",
  ui_story_5063_50630302_2_dialog_content = "That black-robed woman disappeared just as quickly too. Where could she have gone?",
  ui_story_5063_50630302_3_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5063_50630302_4_dialog_content = "Urgh! M-My apologies!",
  ui_story_5063_50630302_5_dialog_content = "I was running so quickly that I didn't notice you there... Are you alright?",
  ui_story_5063_50630302_6_dialog_content = "Ugh...",
  ui_story_5063_50630302_7_dialog_content = "I-I'm fine. Please don't blame yourself, lady knight.",
  ui_story_5063_50630302_8_dialog_content = "I was in a hurry as well, and I failed to notice my surroundings...",
  ui_story_5063_50630302_9_dialog_content = "If anything, I should be the one apologizing!",
  ui_story_5063_50630302_10_dialog_content = "Please don't. I was the one who ran into you, not the other way around.",
  ui_story_5063_50630302_11_dialog_content = "Were you hurt at all?",
  ui_story_5063_50630302_12_dialog_content = "You should have a doctor examine you, just to be safe. And I will personally cover any and all medical expenses.",
  ui_story_5063_50630302_13_dialog_content = "It was just a bump and a fall, lady knight... I appreciate your generosity, but troubling a doctor over this seems a bit unnecessary.",
  ui_story_5063_50630302_14_dialog_content = "Besides, you have more pressing matters to attend to, yes? I would feel terrible if my own foolishness interrupted your noble duties.",
  ui_story_5063_50630302_15_dialog_content = "... At least let me help you to your feet.",
  ui_story_5063_50630302_16_dialog_content = "You dropped a couple of things as well. Are you sure you have everything?",
  ui_story_5063_50630302_17_dialog_content = "Yes, Lady Knight. Nothing appears to be missing.",
  ui_story_5063_50630302_18_dialog_content = "Understood. If you start to feel unwell, please come see me right away. My name is Irridon Novek.",
  ui_story_5063_50630302_19_dialog_content = "Oh, before I forget, did you happen to see a suspicious character running through here just now?",
  ui_story_5063_50630302_20_dialog_content = "A suspicious character? N-No, I don't think so...",
  ui_story_5063_50630302_21_dialog_content = "Hmm? Pardon me, Miss, but... is something the matter?",
  ui_story_5063_50630302_22_dialog_content = "Don't be afraid. As a fellow graduate of the Dawn Academy, I may be able to help.",
  ui_story_5063_50630302_23_dialog_content = "Really? Th-Thank the Light... I'm still just a nun-in-training. You may call me <color=#FFB400>Pam</color>.",
  ui_story_5063_50630302_24_dialog_content = "The reason I was in such a hurry is—",
  ui_story_5063_50630302_25_dialog_content = "We've found her, Lady Nodirri! She's over here!",
  ui_story_5063_50630302_26_dialog_content = "There you are, Pam.",
  ui_story_5063_50630302_27_dialog_content = "Our teacher asked us to retrieve the <color=#FFB400>Dawn Emblem</color> in your possession. May I please have it back?",
  ui_story_5063_50630302_28_dialog_content = "I... I don't think so, no.",
  ui_story_5063_50630302_29_dialog_content = "Huh? That... That's hardly your decision to make.",
  ui_story_5063_50630302_30_dialog_content = "While the academy entrusted you with that emblem for this semester, it doesn't truly belong to you. Dawn Emblems are meant to be passed on between students.",
  ui_story_5063_50630302_31_dialog_content = "Considering that this is the last day of the semester, you have no choice but to return it. Otherwise... How will I explain this to our teacher?",
  ui_story_5063_50630302_32_dialog_content = "Why can't you just give it back?",
  ui_story_5063_50630302_33_dialog_content = "If you like it so much, earn it back next semester.",
  ui_story_5063_50630302_34_dialog_content = "You could at least explain yourself to us, Pam.",
  ui_story_5063_50630302_35_dialog_content = "I can't return it... Because the emblem has been stolen.",
  ui_story_5063_50630302_36_dialog_content = "What? But how? How could you allow something so precious to be stolen?!",
  ui_story_5063_50630302_37_dialog_content = "I...",
  ui_story_5063_50630302_38_dialog_content = "Why do you say it's been \"stolen\"?",
  ui_story_5063_50630302_39_dialog_content = "Are you trying to hide that you lost it accidentally?",
  ui_story_5063_50630302_40_dialog_content = "Or perhaps you want to keep it for yourself! I mean, that emblem is solid gold and worth quite a bit.",
  ui_story_5063_50630302_41_dialog_content = "Please calm down, everyone. As a Justice Knight, I was once a student of the Dawn Academy as well.",
  ui_story_5063_50630302_42_dialog_content = "If Pam's Dawn Emblem was truly stolen, then this is now a criminal matter worthy of investigation!",
  ui_story_5063_50630302_43_dialog_content = "Rest assured, Pam, I won't rest until the culprit has been apprehended and brought to justice.",
  ui_story_5063_50630302_44_dialog_content = "Truth be told, there is someone whom I suspect of stealing it...",
  ui_story_5063_50630302_45_dialog_content = "It's one of my classmates. To avoid causing a scene, I wanted to confront her in private.",
  ui_story_5063_50630302_46_dialog_content = "Who knows if there really is such a person? How do we know if you're not just making it all up?",
  ui_story_5063_50630302_47_dialog_content = "You have a point... Pam's being all stammering as if she's hiding something.",
  ui_story_5063_50630302_48_dialog_content = "If there's actually someone suspicious, just speak up, and we'll all help you get it back.",
  ui_story_5063_50630302_49_dialog_content = "I...",
  ui_story_5063_50630302_50_dialog_content = "Don't be afraid, Pam. Tell us, and we will retrieve the Dawn Emblem and prove your innocence!",
  ui_story_5063_50630302_51_dialog_content = "Actually... I found something near the place where my emblem went missing. It was a handkerchief belonging to one of my classmates.",
  ui_story_5063_50630302_52_dialog_content = "Huh? Why are you looking at me?",
  ui_story_5063_50630302_53_dialog_content = "Because the handkerchief belongs to you, Nodirri.",
  ui_story_5063_50630302_54_dialog_content = "Are you accusing me of something?",
  ui_story_5063_50630302_55_dialog_content = "I actually lost that handkerchief a few days ago... Plus, it's not like I haven't had the emblem before!",
  ui_story_5063_50630302_56_dialog_content = "Only poor people would find value in stealing a solid-gold emblem like that.",
  ui_story_5063_50630302_57_dialog_content = "As a Lumopolis noble, why would I stoop to something as shameful as thievery? My family already has more than enough wealth.",
  ui_story_5063_50630302_58_dialog_content = "I also find it strange, but...",
  ui_story_5063_50630302_59_dialog_content = "Could it be that I am mistaken?",
  ui_story_5063_50630302_60_dialog_content = "Pam... I never took you for this type of villain. You're clearly shifting the blame away from yourself, aren't you?",
  ui_story_5063_50630302_61_dialog_content = "I'm not! White Night up high, I swear that every word I've spoken is the truth. If I am lying, then may the God of Light strike me down where I stand!",
  ui_story_5063_50630302_62_dialog_content = "Do you happen to remember what happened before and after your emblem went missing?",
  ui_story_5063_50630302_63_dialog_content = "Yes, I was in the self-study room when I removed it from my dress. I was planning to give it back to my teacher.",
  ui_story_5063_50630302_64_dialog_content = "But suddenly, I heard a kitten crying out in pain from outside the window. I left and searched all over, but I could not find it.",
  ui_story_5063_50630302_65_dialog_content = "When I returned to the room, my Dawn Emblem had disappeared. The only thing I found was that handkerchief...",
  ui_story_5063_50630302_66_dialog_content = "I see. Please leave the investigation to me then.",
  ui_story_5063_50630303_1_dialog_content = "<color=#e8d9bb>On the verdant grass of Dawn Academy, something sparkles brightly.</color>",
  ui_story_5063_50630303_2_dialog_content = "<color=#e8d9bb>Irridon carefully pushes aside the greenery and discovers a gilded quill.</color>",
  ui_story_5063_50630303_3_dialog_content = "<color=#FFB400>A quill</color>?",
  ui_story_5063_50630303_4_dialog_content = "It's from back then...",
  ui_story_5063_50630303_5_dialog_content = "So what did the high and mighty Irridon want with you just now?",
  ui_story_5063_50630303_6_dialog_content = "She said she saw me in a bind without a pen, so she lent me her gilded quill.",
  ui_story_5063_50630303_7_dialog_content = "It's just a gilded quill, and everyone's got one. What's there to show off?",
  ui_story_5063_50630303_8_dialog_content = "Exactly. And remember how she walks around with that indifferent face, acting like she's all high and mighty?",
  ui_story_5063_50630303_9_dialog_content = "She's only got these grades because of <color=#FFB400>her father</color>. Anyway, don't you find it gross using her stuff?",
  ui_story_5063_50630303_10_dialog_content = "That's why I tossed it away ages ago...",
  ui_story_5063_50630303_11_dialog_content = "Nicely done.",
  ui_story_5063_50630303_12_dialog_content = "I never thought I'd find it again after all these years.",
  ui_story_5063_50630303_13_dialog_content = "Wait... Has it really been that long? Why can't I seem to remember?",
  ui_story_5063_50630303_14_dialog_content = "Maybe it's best if I forget, after all.",
  ui_story_5063_50630304_1_dialog_content = "Hmm? This grade report is almost perfect... This is a rare sight, even at the Dawn Academy.",
  ui_story_5063_50630304_2_dialog_content = "Who could have forgotten something so important in the academy courtyard? I can hardly make out the name on it...",
  ui_story_5063_50630304_3_dialog_content = "\"<color=#FFB400>Irridon Novek</color>\"? Wait... This is mine!",
  ui_story_5063_50630304_4_dialog_content = "...",
  ui_story_5063_50630304_5_dialog_content = "At first, I thought this would make my father happy.",
  ui_story_5063_50630304_6_dialog_content = "But when I showed it to him, his expression didn't change at all.",
  ui_story_5063_50630304_7_dialog_content = "To him, this was something I was supposed to accomplish. He told me not to waste his time.",
  ui_story_5063_50630304_8_dialog_content = "I was already prepared for that kind of response... But that day, he stepped away from his work just to criticize me.",
  ui_story_5063_50630304_9_dialog_content = "He asked me why I had no friends at the Dawn Academy, and why I hadn't maintained a better standing amongst my peers.",
  ui_story_5063_50630304_10_dialog_content = "My father believed that I wasn't trying my best, and that my actions would tarnish our family's good name. He was worried that his work would be affected...",
  ui_story_5063_50630304_11_dialog_content = "I didn't know what to say. All I could do was hang my head in shame.",
  ui_story_5063_50630304_12_dialog_content = "\"Useless!\" ... For a long time afterward, this was my father's most common way of addressing me.",
  ui_story_5063_50630304_13_dialog_content = "Am I truly useless...?",
  ui_story_5063_50630304_14_dialog_content = "Did I not try my best...?",
  ui_story_5063_50630601_1_dialog_content = "How goes the investigation, Justice Knight?",
  ui_story_5063_50630601_2_dialog_content = "You appear to be a new recruit anyway... I hate to pressure you like this, but time is running out.",
  ui_story_5063_50630601_3_dialog_content = "Perhaps I should just report this to our teachers, and let the academy handle the matter instead?",
  ui_story_5063_50630601_4_dialog_content = "That won't be necessary. I've already made considerable progress, but I still have one last question for you. Tell me, when exactly did you lose your handkerchief?",
  ui_story_5063_50630601_5_dialog_content = "Haven't I already answered that question? I told you before, I lost it a few days ago.",
  ui_story_5063_50630601_6_dialog_content = "The academy guard saw you open the door to the self-study room with your handkerchief earlier. Would you care to explain?",
  ui_story_5063_50630601_7_dialog_content = "I thought he was asleep the whole time...",
  ui_story_5063_50630601_8_dialog_content = "So you admit that you entered the self-study room earlier today?",
  ui_story_5063_50630601_9_dialog_content = "Wait... I smell foul play. You've been on Pam's side from the very beginning, haven't you? Tell me, what kind of deal have you made with her?",
  ui_story_5063_50630601_10_dialog_content = "You didn't even bother searching her for the missing item when everyone was present!",
  ui_story_5063_50630601_11_dialog_content = "But I... I only asked the lady knight to help because I couldn't find my Dawn Emblem!",
  ui_story_5063_50630601_12_dialog_content = "You say that, but how do we know you're not lying?",
  ui_story_5063_50630601_13_dialog_content = "I-I have nothing to hide! Search me, if you must!",
  ui_story_5063_50630601_14_dialog_content = "As you wish.",
  ui_story_5063_50630601_15_dialog_content = "Everyone, just in case, let's go ahead and search.",
  ui_story_5063_50630601_16_dialog_content = "And don't forget about Pam's bag!",
  ui_story_5063_50630601_17_dialog_content = "I found something... What's this?!",
  ui_story_5063_50630601_18_dialog_content = "A Dawn Emblem?",
  ui_story_5063_50630601_19_dialog_content = "So it was on your person all along!",
  ui_story_5063_50630601_20_dialog_content = "You shameless liar... Does this emblem truly mean so much to you?",
  ui_story_5063_50630601_21_dialog_content = "N-No... How could this be? It wasn't in my pack when I searched it...",
  ui_story_5063_50630601_22_dialog_content = "What could have compelled you to do such a thing? Tell us, and we might be willing to understand it.",
  ui_story_5063_50630601_23_dialog_content = "President Nodirri, don't sympathize with her. She's already broken the laws in Lumopolis!",
  ui_story_5063_50630601_24_dialog_content = "Justice Knight, what are you waiting for? Arrest her already!",
  ui_story_5063_50630601_25_dialog_content = "The case is still under investigation.",
  ui_story_5063_50630601_26_dialog_content = "What?",
  ui_story_5063_50630601_27_dialog_content = "This Dawn Emblem isn't made of solid gold... In fact, it appears to be a <color=#FFB400>counterfeit</color>.",
  ui_story_5063_50630601_28_dialog_content = "Lady Irridon... This is no counterfeit, at all. I can assure you, this is the emblem that I lost.",
  ui_story_5063_50630601_29_dialog_content = "Don't think we can't see through your charade! You planted this fake in your pack so you could keep the real one hidden, didn't you?!",
  ui_story_5063_50630601_30_dialog_content = "You're wrong! The golden emblem is so precious that I was worried I wouldn't take good enough care of it...",
  ui_story_5063_50630601_31_dialog_content = "So I requested a different Dawn Emblem from the Academy, one that wasn't made from real gold.",
  ui_story_5063_50630601_32_dialog_content = "I know this emblem is virtually worthless, but the honor it brings to me is more than enough.",
  ui_story_5063_50630601_33_dialog_content = "Now you're just making things up! I've never heard of the Dawn Academy providing fake emblems to its students!",
  ui_story_5063_50630601_34_dialog_content = "But I'm not! Just ask our teacher... You'll see that I'm telling the truth if you do!",
  ui_story_5063_50630601_35_dialog_content = "If this emblem truly has no monetary value, then Pam would have no motive to steal it.",
  ui_story_5063_50630601_36_dialog_content = "President Nodirri, shall we go ask the teacher how to handle this?",
  ui_story_5063_50630601_37_dialog_content = "That's enough, all of you!",
  ui_story_5063_50630601_38_dialog_content = "If money isn't her motive, then it can only be one thing... It's slander! She's been trying to tarnish my reputation from the very beginning!",
  ui_story_5063_50630601_39_dialog_content = "With me out of the picture, Pam would have no trouble earning a place in the Lumopolis Temple as a nun-in-training! Isn't that right?!",
  ui_story_5063_50630601_40_dialog_content = "Th-That's not it at all...!",
  ui_story_5063_50630601_41_dialog_content = "You were a fool to do this, Pam. Your actions have only led you further and further away from the temple and its glory.",
  ui_story_5063_50630601_42_dialog_content = "Besides, someone of your lowly status has no right to ascend to the Lumopolis Temple!",
  ui_story_5063_50630601_43_dialog_content = "And even if you did manage to get in, the other nobles and their children would trample you into the dust! Are you truly this clueless?!",
  ui_story_5063_50630601_44_dialog_content = "Something doesn't add up. When I accidentally ran into Pam earlier, the contents of her pack were strewn all over the ground.",
  ui_story_5063_50630601_45_dialog_content = "I don't recall seeing this emblem among her dropped possessions, so how did it appear out of thin air?",
  ui_story_5063_50630601_46_dialog_content = "Unless... Someone put it in my pack after our encounter?",
  ui_story_5063_50630601_47_dialog_content = "It's one thing to play such a childish trick on others, but to drag a Justice Knight of Lumopolis into the matter? Have they no shame?!",
  ui_story_5063_50630601_48_dialog_content = "Whoever is responsible for this must confess immediately, or I will not show any leniency.",
  ui_story_5063_50630601_49_dialog_content = "Lady Irridon!",
  ui_story_5063_50630601_50_dialog_content = "My Dawn Emblem is back in my possession, and it doesn't appear to be damaged in any way. That's more than enough to put my mind at ease.",
  ui_story_5063_50630601_51_dialog_content = "That's all well and good, but the matter has become more complicated than that.",
  ui_story_5063_50630601_52_dialog_content = "But... But it's possible that I simply didn't notice it earlier, isn't it?",
  ui_story_5063_50630601_53_dialog_content = "Hmph, that appears to be the case to me. You should be more careful next time, lest you waste everyone's time with your childish antics again. Let's go, everyone!",
  ui_story_5063_50630601_54_dialog_content = "Well? Are you coming or not?!",
  ui_story_5063_50630601_55_dialog_content = "Yes, President Nodirri.",
  ui_story_5063_50630601_56_dialog_content = "Why did you choose to let her go, Pam? She was clearly the culprit!",
  ui_story_5063_50630601_57_dialog_content = "Because she didn't commit anything truly heinous... It was just a momentary lapse of scruples, nothing more. Besides, I'm certain her heart is already full of guilt and remorse.",
  ui_story_5063_50630601_58_dialog_content = "The God of Light teaches us to be forgiving. As a nun-in-training, I have no right to go against our teachings.",
  ui_story_5063_50630601_59_dialog_content = "I believe the God of Light will guide her steps and help her become a better person... White Night up high.",
  ui_story_5063_50630601_60_dialog_content = "Is that so? Heh, very well then. Even if this incident had never happened, I'm positive that the Lumopolis Temple would have chosen you to stay.",
  ui_story_5063_50630601_61_dialog_content = "Huh? Th-They still haven't made their decision, you know...",
  ui_story_5063_50630601_62_dialog_content = "I just wish I had a classmate like you when I was still at the Academy. Maybe we... Could have been friends.",
  ui_story_5063_50630601_63_dialog_content = "But you're such a valiant and dutiful knight, Lady Irridon! I'm sure you had plenty of friends at the Academy!",
  ui_story_5063_50630601_64_dialog_content = "Quite the opposite, actually. Everyone thought that my achievements were simply a result of being my father's daughter. To say I was detested by my peers would be an understatement.",
  ui_story_5063_50630601_65_dialog_content = "Even my father started to believe the rumors they spread about me. It was... A very lonely time in my past.",
  ui_story_5063_50630601_66_dialog_content = "Then let's be friends now!",
  ui_story_5063_50630601_67_dialog_content = "We may not be classmates, but we can still be great friends! Our encounter must have been perfectly planned by fate!",
  ui_story_5063_50630601_68_dialog_content = "Planned... By fate?",
  ui_story_5063_50630601_69_dialog_content = "Of course! Who else could have rescued me but Lady Irridon of the Justice Knights?",
  ui_story_5063_50630601_70_dialog_content = "W-Well, there are plenty of other knights—",
  ui_story_5063_50630601_71_dialog_content = "It's not a crime to acknowledge your own talents and worth, Lady Irridon. Don't you agree?",
  ui_story_5063_50630601_72_dialog_content = "Huh? N-No, I suppose it's not illegal...",
  ui_story_5063_50630601_73_dialog_content = "Now that I think about it, I believe Pittman wants to become a Justice Knight, as well!",
  ui_story_5063_50630601_74_dialog_content = "<color=#FFB400>Pittman</color>? That name sounds somewhat familiar...",
  ui_story_5063_50630601_75_dialog_content = "He's one of my friends. He would be absolutely thrilled to meet an outstanding Justice Knight such as yourself, you know!",
  ui_story_5063_50630601_76_dialog_content = "You think I'm... Outstanding?",
  ui_story_5063_50630601_77_dialog_content = "Of course! I'll be sure to introduce the two of you someday.",
  ui_story_5063_50630601_78_dialog_content = "Oh my, look at the time! I still need to pay my grandfather a visit at his home...",
  ui_story_5063_50630601_79_dialog_content = "Forgive me, Lady Irridon, but I must be going now!",
  ui_story_5063_50630601_80_dialog_content = "The next time we meet, I promise to properly repay you for all that you've done!",
  ui_story_5063_50630701_1_dialog_content = "Am I... Really an outstanding Justice Knight?",
  ui_story_5063_50630701_2_dialog_content = "What kind of Justice Knight lets a criminal walk away...",
  ui_story_5063_50630701_3_dialog_content = "Should I report this to the Chief Judge?",
  ui_story_5063_50630701_4_dialog_content = "Go and arrest madwoman! Don't let me down again!",
  ui_story_5063_50630701_5_dialog_content = "I would only disappoint her even more than I already have...",
  ui_story_5063_50630701_6_dialog_content = "She probably thinks I'm useless, just like my father.",
  ui_story_5063_50630701_7_dialog_content = "In fact... They might just kick me out of the Hall of Justice for this...",
  ui_story_5063_50630701_8_dialog_content = "...",
  ui_story_5063_50630701_9_dialog_content = "Huh? It's her!!",
  ui_story_5063_50630701_10_dialog_content = "She's trying to escape to the Lumopolis Courtyard from the Stairway to the Skies...",
  ui_story_5063_50630701_11_dialog_content = "Good, at least the Lumopolis Gardens are safe from her actions!",
  ui_story_5063_50630701_12_dialog_content = "Wait, that's no cause for relief! I have to catch her!",
  ui_story_5063_50630701_13_dialog_content = "Protection! Loyalty! Glory!",
  ui_story_5063_50630701_14_dialog_content = "Those strange soldiers are back again!",
  ui_story_5063_50630701_15_dialog_content = "Please stay out of my way! You're obstructing my pursuit of a criminal!",
  ui_story_5063_50630802_1_dialog_content = "Halt—!",
  ui_story_5063_50630802_2_dialog_content = "She disappeared again? I should ask the people up ahead if they saw her.",
  ui_story_5063_50630802_3_dialog_content = "We can always go to the Hall of Justice, if need be!",
  ui_story_5063_50630802_4_dialog_content = "My thoughts exactly. I swear I will get to the bottom of this!",
  ui_story_5063_50630802_5_dialog_content = "Pardon me, good sirs, but did either of you notice a suspicious woman in black running through this area?",
  ui_story_5063_50630802_6_dialog_content = "I haven't seen a woman in black, but this guy in front of us, Jerry, seems very suspicious to me.",
  ui_story_5063_50630802_7_dialog_content = "Here is your chance, Lord Major! Go ahead, share your thoughts with the Hall of Justice!",
  ui_story_5063_50630802_8_dialog_content = "Accosting innocent people on the street, only to blindly interrogate them... Is this part of the nobility's upbringing, as well?!",
  ui_story_5063_50630802_9_dialog_content = "Know your place, servant! The upbringing of nobles hardly concerns a lowly peasant such as yourself!",
  ui_story_5063_50630802_10_dialog_content = "Public disturbances are in direct violation of Lumopolis law. I suggest the two of you calm down right now.",
  ui_story_5063_50630802_11_dialog_content = "Now what seems to be the problem? I would be more than happy to mediate.",
  ui_story_5063_50630802_12_dialog_content = "You are a Justice Knight, yes? Please forgive my outburst just now.",
  ui_story_5063_50630802_13_dialog_content = "You've come at just the right time. I would like to file a report against this shamelessly-greedy servant! You'll help me, won't you?",
  ui_story_5063_50630802_14_dialog_content = "Again, please just calm down and tell me exactly what has happened.",
  ui_story_5063_50630802_15_dialog_content = "Today, my elderly father suddenly and <color=#FFB400>mysteriously passed away</color>.",
  ui_story_5063_50630802_16_dialog_content = "I came to handle his estate as soon as I received the news, but this man here— a servant in my father's employ known as Jerry— refuses to let me enter the premises.",
  ui_story_5063_50630802_17_dialog_content = "He presented me with this strange <color=#FFB400>will</color>, saying that my father bequeathed his title and estate entirely to him.",
  ui_story_5063_50630802_18_dialog_content = "The very notion of a father depriving his own son of his family's name and status...",
  ui_story_5063_50630802_19_dialog_content = "I-If this were true, our family would be reduced to common rabble!",
  ui_story_5063_50630802_20_dialog_content = "It's absolutely preposterous, don't you agree? As a knight, I'm sure you do!",
  ui_story_5063_50630802_21_dialog_content = "Barring foul play, it is indeed very uncommon for a noble to relinquish his entire legacy, especially to...",
  ui_story_5063_50630802_22_dialog_content = "To a lowly servant? That's what you were going to say, yes?",
  ui_story_5063_50630802_23_dialog_content = "Am I right to assume that you were born into a life of wealth and nobility, lady knight? A life where all of your wants and needs are satisfied at the snap of a finger?",
  ui_story_5063_50630802_24_dialog_content = "Irrespective of my background, I am a Justice Knight of Lumopolis, and I have a duty to treat both parties fairly and equitably.",
  ui_story_5063_50630802_25_dialog_content = "Now please, share your side of the matter.",
  ui_story_5063_50630802_26_dialog_content = "While it's true that Lord Major is my master's son, the two have always been at odds with one another, and Lord Major rarely visited my master while he was alive.",
  ui_story_5063_50630802_27_dialog_content = "Up until the moment he drew his last breath, I was the one who cared for my master, day and night.",
  ui_story_5063_50630802_28_dialog_content = "Despite my humble background, my master always encouraged me to better myself. Eventually, he began to regard me like his own son.",
  ui_story_5063_50630802_29_dialog_content = "He drafted this will to prove his sincerity and allay my doubts. You'll find that it's completely in accordance with Lumopolis law...",
  ui_story_5063_50630802_30_dialog_content = "I've spoken nothing but the truth! If anything I've said is a lie, then let me be struck down by the God of Light!",
  ui_story_5063_50630802_31_dialog_content = "Don't be deceived by his flowery language, lady knight. The God of Light would never listen to a single word from his lying mouth.",
  ui_story_5063_50630802_32_dialog_content = "As for my seldom visits, my father gave me little choice. The man simply refused to see me.",
  ui_story_5063_50630802_33_dialog_content = "And before you begin to suspect anything, I never wronged my father in any way. He was always very strict with me, and his expectations were always so high...",
  ui_story_5063_50630802_34_dialog_content = "In his eyes, I was nothing but an indolent, ignorant, and complacent son.",
  ui_story_5063_50630802_35_dialog_content = "Despite my best efforts to meet his demands, he was never satisfied. Not once did he acknowledge me as a worthwhile person.",
  ui_story_5063_50630802_36_dialog_content = "Regardless of his dissatisfaction with me, I know my father would have never left behind a will like this.",
  ui_story_5063_50630802_37_dialog_content = "And that is because he was dearly fond of his grandchild, my own daughter.",
  ui_story_5063_50630802_38_dialog_content = "She would visit him often to keep him company and make sure he was well. Denying me is one thing, but he would never deprive his granddaughter of her rightful inheritance!",
  ui_story_5063_50630802_39_dialog_content = "Are you acquainted with your master's granddaughter as well, Jerry?",
  ui_story_5063_50630802_40_dialog_content = "Yes. I was also curious as to why my master didn't leave her with his fortune, but he said she had little need for it.",
  ui_story_5063_50630802_41_dialog_content = "Hahahaha! How utterly ridiculous! I daresay I've never heard a more pathetic lie in my entire life!",
  ui_story_5063_50630802_42_dialog_content = "Just admit it! This is all just a vile scheme to rob us of our livelihoods!",
  ui_story_5063_50630802_43_dialog_content = "Lord Major, you should know by now that I am not a man motivated by wealth. If I was, I never would have stayed at your father's side for so long.",
  ui_story_5063_50630802_44_dialog_content = "Nevertheless, my master made it very clear to me that these are his dying wishes, and I have no intention of dishonoring them!",
  ui_story_5063_50630802_45_dialog_content = "(I feel as though I've seen a similar dilemma before. Was it a case from my academy days?)",
  ui_story_5063_50630802_46_dialog_content = "(I still can't remember... Ugh, why do I feel so light-headed?)",
  ui_story_5063_50630802_47_dialog_content = "Lady Irridon?",
  ui_story_5063_50630802_48_dialog_content = "Father, Jerry... What are you all doing here? Are you all acquainted with each other?",
  ui_story_5063_50630802_49_dialog_content = "Do you know this knight, Pam?",
  ui_story_5063_50630802_50_dialog_content = "Yes, father. Lady Irridon is a friend of mine who recently helped me with a problem. In fact, I was considering inviting her over for dinner...",
  ui_story_5063_50630802_51_dialog_content = "That won't be a problem, right father? After all, you two already seem to know each other.",
  ui_story_5063_50630802_52_dialog_content = "Now if everyone would please excuse me, I'm worried about my grandfather. No one answered the door when I went to visit him just now... Does anyone know why?",
  ui_story_5063_50630802_53_dialog_content = "Pam, your grandfather... Is no longer with us.",
  ui_story_5063_50630802_54_dialog_content = "<size=45>H-He passed away?!</size>",
  ui_story_5063_50630802_55_dialog_content = "But grandfather was always so healthy! How could this have happened?! I don't believe it! This must be some kind of joke!",
  ui_story_5063_50630802_56_dialog_content = "He still hasn't seen my formal acceptance into the Lumopolis Temple, how could he just leave me like this?",
  ui_story_5063_50630802_57_dialog_content = "Father? Jerry? Why do you have those looks on your faces? Please... Tell me this isn't real...",
  ui_story_5063_50630802_58_dialog_content = "(I can't afford to ignore this case, especially since it affects Pam so deeply.)",
  ui_story_5063_50630802_59_dialog_content = "Everyone, please accept my most heart-felt condolences...",
  ui_story_5063_50630802_60_dialog_content = "Allow me to personally handle the investigation of this matter.",
  ui_story_5063_50630803_1_dialog_content = "<color=#e8d9bb>During Irridon's investigation in the house of Pam's Grandpa, she unexpectedly comes across a cane tucked away in a corner, seemingly inconspicuous.</color>",
  ui_story_5063_50630803_2_dialog_content = "A <color=#FFB400>cane</color>...",
  ui_story_5063_50630803_3_dialog_content = "It's exactly the same as my father's!",
  ui_story_5063_50630803_4_dialog_content = "My hands still remember the sting from every mistake I made.",
  ui_story_5063_50630803_5_dialog_content = "That cold, hard, stinging pain...",
  ui_story_5063_50630803_6_dialog_content = "Just seeing one of these canes is enough to send my heart racing.",
  ui_story_5063_50630803_7_dialog_content = "Suddenly, I'm reminded of that terrible scene: my father standing before me, with an Eclipsite's claws sinking deep into his chest...",
  ui_story_5063_50630803_8_dialog_content = "My father never cared for me, so why would he sacrifice his own life for his \"useless\" daughter?",
  ui_story_5063_50630803_9_dialog_content = "I still don't understand. That's why, even now, I'm still too scared to walk past his study...",
  ui_story_5063_50630803_10_dialog_content = "Once I stop being so useless, and become a worthy Justice Knight in the Chief Judge's eyes... Will I have the courage to face my father then?",
  ui_story_5063_50630803_11_dialog_content = "Pam's father, Lord Major, appears to share a similar history with his own father.",
  ui_story_5063_50630803_12_dialog_content = "But for his daughter's sake, he managed to put an end to this vicious cycle in his own time. I doubt it was easy for him.",
  ui_story_5063_50630803_13_dialog_content = "Lord Major... You've done well.",
  ui_story_5063_50630803_14_dialog_content = "As for me... I need to do the same.",
  ui_story_5063_50630804_1_dialog_content = "Is that an official case file lying on the side of the road? What kind of careless oaf could have...",
  ui_story_5063_50630804_2_dialog_content = "Wait! Is this the case file for my current investigation?!",
  ui_story_5063_50630804_3_dialog_content = "It appears the judge presiding over this case found the will to be dubious in nature...",
  ui_story_5063_50630804_4_dialog_content = "The reason being... That the witness present at the will's signing was a servant, not an official notary. Thus, the witness's testimony could not be legally accepted.",
  ui_story_5063_50630804_5_dialog_content = "With the will rendered invalid, the distribution of the deceased's estate fell under the jurisdiction of our common inheritance laws.",
  ui_story_5063_50630804_6_dialog_content = "But how could that be? I need to find the judge who oversaw this case and confront them about this!",
  ui_story_5063_50630804_7_dialog_content = "There's a signature at the bottom...",
  ui_story_5063_50630804_8_dialog_content = "\"<color=#FFB400>Rodell Novek</color>\"?!",
  ui_story_5063_50630804_9_dialog_content = "My <color=#FFB400>father</color> presided over this case?!",
  ui_story_5063_50630804_10_dialog_content = "Does that mean I have to pass the same verdict as him...?",
  ui_story_5063_50630804_11_dialog_content = "Is this truly the only way I can earn his acceptance? By accepting and obeying his every word?",
  ui_story_5063_50630804_12_dialog_content = "Somehow...",
  ui_story_5063_50630804_13_dialog_content = "Somehow I don't think this was the right verdict...",
  ui_story_5063_50631101_1_dialog_content = "(Though the reasons are still unclear, it seems Pam's grandfather really did take his own life. The point of contention, then, centers around his will.)",
  ui_story_5063_50631101_2_dialog_content = "(In form and content, this will was written in perfect accordance with Lumopolis' laws of inheritance.)",
  ui_story_5063_50631101_3_dialog_content = "(The only dispute is that the witness wasn't a noble, but an old servant... However, that is hardly a valid reason for denying the authenticity of a will.)",
  ui_story_5063_50631101_4_dialog_content = "(But if the will is accepted by the court, Pam and her family will lose their status as nobles. Wouldn't that affect her future, as well?)",
  ui_story_5063_50631101_5_dialog_content = "(I don't want to risk our friendship because of this... What should I do?)",
  ui_story_5063_50631101_6_dialog_content = "Lady Irridon? I'm not intruding, am I?",
  ui_story_5063_50631101_7_dialog_content = "Please don't misunderstand! I-I simply wish to tell you... Please don't let our acquaintance stand in the way of passing fair judgment!",
  ui_story_5063_50631101_8_dialog_content = "White Night up high. As a Justice Knight of Lumopolis, you have been chosen by the God of Light to serve the people of this city equally and without bias.",
  ui_story_5063_50631101_9_dialog_content = "Pardon me if I sound presumptuous, but please... Don't let our friendship tarnish the sanctity of righteous judgment!",
  ui_story_5063_50631101_10_dialog_content = "Pam...",
  ui_story_5063_50631101_11_dialog_content = "My father taught me long ago that a true servant of justice is an impartial one.",
  ui_story_5063_50631101_12_dialog_content = "Rest assured, I will gather the evidence I need to pass fair and honest judgment!",
  ui_story_5063_50631101_13_dialog_content = "Have you reached a conclusion yet, lady knight?",
  ui_story_5063_50631101_14_dialog_content = "I am eagerly awaiting your judgment as well, milady!",
  ui_story_5063_50631101_15_dialog_content = "I've finally reached a verdict, yes.",
  ui_story_5063_50631101_16_dialog_content = "White Night up high! In accordance with Lumopolis' laws regarding inheritance and final testaments, I hereby declare that this will is legally valid.",
  ui_story_5063_50631101_17_dialog_content = "But the witness was nothing more than a mere servant! Surely you noticed such a blatant violation, yes?!",
  ui_story_5063_50631101_18_dialog_content = "Your haphazard judgment will rock all of Lumopolis to its very foundations!",
  ui_story_5063_50631101_19_dialog_content = "There is no law in Lumopolis that prohibits a person from acting as a witness based purely on their economic standing. This is merely a rumor which exists among members of the nobility.",
  ui_story_5063_50631101_20_dialog_content = "So long as a person is honest, diligent, and clear of any legal wrongdoing, they are perfectly entitled to serve as a trustworthy witness.",
  ui_story_5063_50631101_21_dialog_content = "You... And you call yourself a Justice Knight of Lumopolis?!",
  ui_story_5063_50631101_22_dialog_content = "Father, stop! When a group of noble students accused me of stealing a Dawn Emblem from the Academy, it was Lady Irridon who uncovered the truth behind their actions!",
  ui_story_5063_50631101_23_dialog_content = "Our prejudice towards Mr. Jerry is no different than the prejudice those other nobles showed towards us.",
  ui_story_5063_50631101_24_dialog_content = "In any case, I trust in Lady Irridon and her ability to deliver a just and reasonable judgment.",
  ui_story_5063_50631101_25_dialog_content = "Not you too, Pam...",
  ui_story_5063_50631101_26_dialog_content = "If this was truly grandfather's final wish, we have no choice but to honor it.",
  ui_story_5063_50631101_27_dialog_content = "Sigh, how did things end up like this? And here I thought I could give you just a bit more...",
  ui_story_5063_50631101_28_dialog_content = "Perhaps the old man never wanted a son like me, after all.",
  ui_story_5063_50631101_29_dialog_content = "That's not true at all, father! I know there has always been a great deal of distance between you...",
  ui_story_5063_50631101_30_dialog_content = "But grandfather never complained or spoke poorly of you whenever I visited! You had your own silent way of caring for him as well, didn't you?",
  ui_story_5063_50631101_31_dialog_content = "If both of you had just taken that first step towards each other, I'm certain you could have closed the gap between you!",
  ui_story_5063_50631101_32_dialog_content = "Father...",
  ui_story_5063_50631101_33_dialog_content = "(Do my father and I have a similar, untraversable distance between us?)",
  ui_story_5063_50631101_34_dialog_content = "(Even with things as they are now, my verdict is still completely different from his.)",
  ui_story_5063_50631101_35_dialog_content = "(Could it be that... My judgment is still being affected by my emotions?!)",
  ui_story_5063_50631101_36_dialog_content = "(It wasn't my friendship with Pam, but my desire to rebel against my father... That was what drove me to pass this verdict!)",
  ui_story_5063_50631101_37_dialog_content = "Why have you fallen so silent, Lady Irridon? If it's because of our plight... Then I humbly ask that you refrain from pitying us.",
  ui_story_5063_50631101_38_dialog_content = "It's nothing, I was just reminded of my own father. If he was still with us today... Would he have passed a different verdict?",
  ui_story_5063_50631101_39_dialog_content = "I see. Does this mean you wish to be more like your father, Lady Irridon?",
  ui_story_5063_50631101_40_dialog_content = "Absolutely not!",
  ui_story_5063_50631101_41_dialog_content = "Forgive me if I misspoke, but are you truly so against the idea?",
  ui_story_5063_50631101_42_dialog_content = "Otherwise, why would your father's judgment concern you so greatly?",
  ui_story_5063_50631101_43_dialog_content = "I...",
  ui_story_5063_50631101_44_dialog_content = "You have a point. Why am I so concerned about the verdict my father would reach? And why did I become a Justice Knight in the first place?",
  ui_story_5063_50631101_45_dialog_content = "<size=45>This is it! Apprehend everyone in this house!</size>",
  ui_story_5063_50631101_46_dialog_content = "<size=45>Yes!</size>",
  ui_story_5063_50631101_47_dialog_content = "H-Huh?!",
  ui_story_5063_50631101_48_dialog_content = "Pam! Let go of my daughter, you brutes!!",
  ui_story_5063_50631101_49_dialog_content = "Is this truly happening? The will my master wrote... It's been accepted by the court?",
  ui_story_5063_50631101_50_dialog_content = "Why are you apprehending this family? Whose orders are you following?",
  ui_story_5063_50631101_51_dialog_content = "Members of the Pyrrhus house ignored warnings and were researching the red crystals. The City Lord and Chief Judge have issued orders for the arrest of all the family members.",
  ui_story_5063_50631101_52_dialog_content = "These are the judgments and arrest warrants! Uninvolved parties, leave immediately, or we will arrest you all!",
  ui_story_5063_50631101_53_dialog_content = "W-Wait! I'm not a part of this family!",
  ui_story_5063_50631101_54_dialog_content = "Whether you are or not, we will investigate it thoroughly. Now, move along!",
  ui_story_5063_50631101_55_dialog_content = "Pam...",
  ui_story_5063_50631101_56_dialog_content = "Forgive me, Lady Irridon... I meant to invite you for dinner with my family, but it appears we'll have to reschedule.",
  ui_story_5063_50631101_57_dialog_content = "Stay strong! I'll find a way to save you!",
  ui_story_5063_50631101_58_dialog_content = "You've already done so much for me, so please don't trouble yourself for my sake any further... It would only weigh upon my heart even more.",
  ui_story_5063_50631101_59_dialog_content = "Even I know that researching the red crystals is strictly forbidden. Though my parents and I have committed no crime...",
  ui_story_5063_50631101_60_dialog_content = "When one of our own is found guilty, our entire family bears the weight of their sins.",
  ui_story_5063_50631101_61_dialog_content = "But don't worry. I will take this as an opportunity to show the God of Light my repentance and devotion, and continue striving to become a nun of the Lumopolis Temple!",
  ui_story_5063_50631101_62_dialog_content = "Should that day ever come, I'm certain you will also be a fully-fledged judge of the Hall of Justice.",
  ui_story_5063_50631101_63_dialog_content = "I'll... I'll do my best! I'll become a pure and righteous judge someday!",
  ui_story_5063_50631101_64_dialog_content = "Move it! No time for chit-chat!",
  ui_story_5063_50631101_65_dialog_content = "Till next we meet, my friend!",
  ui_story_5063_50631101_66_dialog_content = "Good-bye...",
  ui_story_5063_50631103_1_dialog_content = "Is this another one of my father's verdicts?",
  ui_story_5063_50631103_2_dialog_content = "No... This is a private investigation report written by my father himself.",
  ui_story_5063_50631103_3_dialog_content = "\"Prior to passing away, the late baron discovered that his entire family would soon be arrested.\"",
  ui_story_5063_50631103_4_dialog_content = "\"Fearing that his son and granddaughter would be implicated, he devised one final, desperate plan.\"",
  ui_story_5063_50631103_5_dialog_content = "\"By conferring his title and estate to his closest servant in his will, the late baron believed that his family would be spared.\"",
  ui_story_5063_50631103_6_dialog_content = "What...? How and when did my father uncover such shocking details?",
  ui_story_5063_50631103_7_dialog_content = "Even if it was to protect his family, Pam's grandfather had no right to implicate his innocent servant!",
  ui_story_5063_50631103_8_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631103_9_dialog_content = "So my father was aware of the baron's intentions all along. Is that why he chose to nullify his will?",
  ui_story_5063_50631103_10_dialog_content = "As expected... Father's verdict was correct, after all...",
  ui_story_5063_50631103_11_dialog_content = "Wh-What have I done...?",
  ui_story_5063_50631201_1_dialog_content = "I've searched the entire Lumopolis Courtyard, but still no sign of the woman in black. Could she have escaped into Lower Lumopolis?",
  ui_story_5063_50631201_2_dialog_content = "I never made many trips to Lower Lumopolis in the past... Even the mood is completely different from the upper parts of the city.",
  ui_story_5063_50631201_3_dialog_content = "I can feel countless eyes watching me as I walk through the streets... Is a Justice Knight's presence truly so out of place here?",
  ui_story_5063_50631201_4_dialog_content = "What are you doing here, Justice Knight?",
  ui_story_5063_50631201_5_dialog_content = "Ch-Chief Judge?!",
  ui_story_5063_50631201_6_dialog_content = "I... M-My apologies, but due to my own inadequacy, I still haven't apprehended the woman in black.",
  ui_story_5063_50631201_7_dialog_content = "But during my pursuit, I managed to solve a number of unrelated cases for some of the local residents...",
  ui_story_5063_50631201_8_dialog_content = "The woman in black? What woman in black?",
  ui_story_5063_50631201_9_dialog_content = "Huh? The one who barged into the Hall of Justice and requested that you clear her name...",
  ui_story_5063_50631201_10_dialog_content = "Hmm... now that you mention it, I do vaguely recall such a person.",
  ui_story_5063_50631201_11_dialog_content = "But we can put that on hold for now. I've got a more important task for you.",
  ui_story_5063_50631201_12_dialog_content = "We've got intel suggesting that Mirren Gautier might be involved in treason. Look into whether this lead holds any truth.",
  ui_story_5063_50631201_13_dialog_content = "A-Are you certain you wish to leave me with such an important task?",
  ui_story_5063_50631201_14_dialog_content = "Er, I mean... Thank you for placing your trust in me, Chief Judge! I will begin my investigation into Mirren Gautier's suspected treason right away...",
  ui_story_5063_50631201_15_dialog_content = "Wait... Someone plans to rebel against the city?!",
  ui_story_5063_50631201_16_dialog_content = "This task concerns the survival of Lumopolis, which means it must be carried out flawlessly, with no room for error. Do you understand?",
  ui_story_5063_50631201_17_dialog_content = "Yes, Chief Judge!",
  ui_story_5063_50631201_18_dialog_content = "I won't allow anyone to defile the city I've sworn to protect!",
  ui_story_5063_50631201_19_dialog_content = "Nor will I allow myself to disappoint you, Chief Judge...",
  ui_story_5063_50631201_20_dialog_content = "Protection! Loyalty! Glory!",
  ui_story_5063_50631201_21_dialog_content = "Not again... Where do they keep coming from?!",
  ui_story_5063_50631201_22_dialog_content = "Please retreat to safety, Chief Judge! I can deal with them!",
  ui_story_5063_50631201_23_dialog_content = "Attack!",
  ui_story_5063_50631302_1_dialog_content = "(The Chief Judge said that she couldn't see those strange guards...)",
  ui_story_5063_50631302_2_dialog_content = "(Could it be that only I can see them?)",
  ui_story_5063_50631302_3_dialog_content = "Do my eyes deceive me... Is that you, Lady Irridon?",
  ui_story_5063_50631302_4_dialog_content = "Pam?!",
  ui_story_5063_50631302_5_dialog_content = "White Night up high! It really is you! But what are you doing in Lower Lumopolis?",
  ui_story_5063_50631302_6_dialog_content = "I thought I wouldn't see you again for a much longer time...",
  ui_story_5063_50631302_7_dialog_content = "I have a job to do down here. Have you... been well?",
  ui_story_5063_50631302_8_dialog_content = "Yes! As you can see, my body and spirit are in perfect health!",
  ui_story_5063_50631302_9_dialog_content = "I heard your entire family was stripped of their Luminatics...",
  ui_story_5063_50631302_10_dialog_content = "This... was only to be expected. After all, our family was responsible for committing such an unforgivable sin.",
  ui_story_5063_50631302_11_dialog_content = "By Lumopolis' law, our punishment is entirely fitting.",
  ui_story_5063_50631302_12_dialog_content = "...I-In any case, I see this all as a brand-new experience! After all, I had never been to Lower Lumopolis prior to our exile!",
  ui_story_5063_50631302_13_dialog_content = "So long as our family stays together, we can survive anywhere!",
  ui_story_5063_50631302_14_dialog_content = "But what about the Lumopolis Temple probationary...?",
  ui_story_5063_50631302_15_dialog_content = "Well, it's true that I have no way of returning now...",
  ui_story_5063_50631302_16_dialog_content = "But even so, my faith holds fast. I pray to the God of Light every day for absolution, just as I always have in the past.",
  ui_story_5063_50631302_17_dialog_content = "So long as I persevere, I'm certain there will be a place for me in the Lumopolis Temple sometime in the future!",
  ui_story_5063_50631302_18_dialog_content = "Your sheer optimism leaves me speechless...",
  ui_story_5063_50631302_19_dialog_content = "Unlike you, I'm full of doubt and apprehension, so much so that I can't even complete the tasks set before me.",
  ui_story_5063_50631302_20_dialog_content = "There's no need to compare yourself to others, you know? Every single person is unique, and has their own problems to solve in life.",
  ui_story_5063_50631302_21_dialog_content = "In my eyes, Lady Irridon, you are already an outstanding and hard-working person. Are you sure you're not expecting too much of yourself?",
  ui_story_5063_50631302_22_dialog_content = "You... Really think so?",
  ui_story_5063_50631302_23_dialog_content = "Goodness... Why am I the one being comforted, all of a sudden?",
  ui_story_5063_50631302_24_dialog_content = "...But enough about that. If you or your family ever run into any problems, you must tell me right away!",
  ui_story_5063_50631302_25_dialog_content = "Hahaha! Your concern is most appreciated, Lady Irridon!",
  ui_story_5063_50631302_26_dialog_content = "Oh? Is it lunchtime already? If you haven't eaten yet, would you care to join us?",
  ui_story_5063_50631302_27_dialog_content = "If it isn't too much trouble, then yes...",
  ui_story_5063_50631302_28_dialog_content = "After all, this is... The first time a friend has ever invited me to eat together. It would be my honor to join you!",
  ui_story_5063_50631302_29_dialog_content = "The food will be ready in just a few minutes!",
  ui_story_5063_50631302_30_dialog_content = "Ever since we first met, I've wanted to invite you to have dinner with my family...",
  ui_story_5063_50631302_31_dialog_content = "I was beginning to think it was never meant to be... But then fate brought us together yet again, here in Lower Lumopolis!",
  ui_story_5063_50631302_32_dialog_content = "I know it isn't dinner, and there aren't many dishes to choose from...",
  ui_story_5063_50631302_33_dialog_content = "But through study and practice, I've learned how to make decent meals from the scarce ingredients available to us here!",
  ui_story_5063_50631302_34_dialog_content = "Yes, and you have me to thank for the cooking skills you inherited, Pam! Hahahaha!",
  ui_story_5063_50631302_35_dialog_content = "I'm just thankful that I didn't inherit your boastfulness as well, father!",
  ui_story_5063_50631302_36_dialog_content = "P-Pam! How could you ridicule your poor father in front of Lady Irridon?!",
  ui_story_5063_50631302_37_dialog_content = "Heehee, I'm only teasing! After all, mother does it to you all the time, doesn't she?",
  ui_story_5063_50631302_38_dialog_content = "You must forgive my daughter for her silly behavior, Lady Irridon. Please, help yourself.",
  ui_story_5063_50631302_39_dialog_content = "I can assure you, you won't taste anything like this in the Lumopolis Gardens! Hahahaha!",
  ui_story_5063_50631302_40_dialog_content = "I know it doesn't look particularly extravagant, but...",
  ui_story_5063_50631302_41_dialog_content = "Munch...",
  ui_story_5063_50631302_42_dialog_content = "Well? Does it suit your tastes?",
  ui_story_5063_50631302_43_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631302_44_dialog_content = "...It's so delicious.",
  ui_story_5063_50631302_45_dialog_content = "In fact, my body is surging with newfound energy after tasting it!",
  ui_story_5063_50631302_46_dialog_content = "I never knew that a bowl of soup could make me feel so incredible...",
  ui_story_5063_50631302_47_dialog_content = "You didn't happen to add a Lumina potion to it, did you Pam?",
  ui_story_5063_50631302_48_dialog_content = "And just where on earth would I find the money for such an expensive ingredient, Lady Irridon?",
  ui_story_5063_50631302_49_dialog_content = "No, if anything... What you're tasting could only be described as <color=#FFB400>a family's love</color>.",
  ui_story_5063_50631302_50_dialog_content = "\"A family's love...\"",
  ui_story_5063_50631302_51_dialog_content = "Again, you must forgive my daughter, Lady Irridon. Her speech can be a bit confusing at times.",
  ui_story_5063_50631302_52_dialog_content = "On the contrary, I'm very grateful to Pam for sharing her thoughts with me.",
  ui_story_5063_50631302_53_dialog_content = "Not only that, but I believe I owe you an apology with regards to your father's will...",
  ui_story_5063_50631302_54_dialog_content = "There's no need, my lady. It's all in the past now, and I've long since accepted it.",
  ui_story_5063_50631302_55_dialog_content = "When we arrived in Lower Lumopolis, we were no different than the commoners we once viewed with such contempt. At first, I thought our lives would be filled with misery and suffering.",
  ui_story_5063_50631302_56_dialog_content = "But as commoners, I soon discovered that the people around us were far better at helping and caring for one another than any aristocrats I have ever known.",
  ui_story_5063_50631302_57_dialog_content = "In Lumopolis, nobles must often trample on the people beneath them in order to maintain their positions.",
  ui_story_5063_50631302_58_dialog_content = "The only way to avoid it is by shoving others down and trampling on them, instead.",
  ui_story_5063_50631302_59_dialog_content = "At the end of the day, what would be the point of returning to such an exploitative life?",
  ui_story_5063_50631302_60_dialog_content = "My only regret is that Pam lost her chance to join the Lumopolis Temple...",
  ui_story_5063_50631302_61_dialog_content = "But as a branch of the Pyrrhus family, you were never directly responsible for any of their crimes.",
  ui_story_5063_50631302_62_dialog_content = "Not only that, but I can't think of anyone more worthy of becoming a nun than Pam. Her devotion and personality tell me as much.",
  ui_story_5063_50631302_63_dialog_content = "When I finish with my current assignment, I'll be sure to report this to the Chief Judge. Perhaps she will allow her to return to the Lumopolis Temple!",
  ui_story_5063_50631303_1_dialog_content = "\"The Pyrrhus family, in conjunction with the Gautier family, made use of augmented Eclipsites to stage a violent rebellion...\"",
  ui_story_5063_50631303_2_dialog_content = "\"Every member of their respective families has been sentenced to death. In the event of further resistance, they shall be executed on the spot.\"",
  ui_story_5063_50631303_3_dialog_content = "I-Is this another one of my father's verdicts...?",
  ui_story_5063_50631303_4_dialog_content = "But this is completely contrary to my investigation's findings!",
  ui_story_5063_50631303_5_dialog_content = "It's true that both families were exiled to Lower Lumopolis as a result of the Pyrrhus family's research on the red crystals...",
  ui_story_5063_50631303_6_dialog_content = "But right now, the ones colluding with the Eclipsites to persecute the Pyrrhus family are none other than Mirren Gautier and his kinsmen!",
  ui_story_5063_50631303_7_dialog_content = "Surely, my father couldn't have missed such an important detail...",
  ui_story_5063_50631303_8_dialog_content = "So why would he pass judgment like this?",
  ui_story_5063_50631303_9_dialog_content = "This case impacts all of Lumopolis and its safety... Am I truly confident enough in my own judgment to overturn my father's verdict?",
  ui_story_5063_50631303_10_dialog_content = "Could it be... Did he discover something else?",
  ui_story_5063_50631303_11_dialog_content = "In any case, there's no reason to continue persecuting an innocent family over this!",
  ui_story_5063_50631303_12_dialog_content = "Father...",
  ui_story_5063_50631303_13_dialog_content = "It seems the distance between us... has only grown greater...",
  ui_story_5063_50631601_1_dialog_content = "...That concludes my investigation report.",
  ui_story_5063_50631601_2_dialog_content = "Good, I'll report these investigation results to the Chief Judge immediately!",
  ui_story_5063_50631601_3_dialog_content = "You have my gratitude!",
  ui_story_5063_50631601_4_dialog_content = "Now then, I still have one last thing to do...",
  ui_story_5063_50631601_5_dialog_content = "Have you been making progress on your mission, Lady Irridon?",
  ui_story_5063_50631601_6_dialog_content = "Er... Yes. In fact, the matter is all but concluded now.",
  ui_story_5063_50631601_7_dialog_content = "Then... Will you be leaving soon?",
  ui_story_5063_50631601_8_dialog_content = "Please don't misunderstand! I simply thought that if you weren't in a hurry, you could come to our home and have dinner with us.",
  ui_story_5063_50631601_9_dialog_content = "Mother and father are preparing a feast as we speak!",
  ui_story_5063_50631601_10_dialog_content = "Ahhhh!",
  ui_story_5063_50631601_11_dialog_content = "<size=45>Purge the traitors! Purge the traitors! Purge the traitors!</size>",
  ui_story_5063_50631601_12_dialog_content = "Why are those guards arresting everyone?!",
  ui_story_5063_50631601_13_dialog_content = "<size=45>Purge the traitors! Purge the traitors! Purge the traitors!</size>",
  ui_story_5063_50631601_14_dialog_content = "(It appears the Chief Judge has already given the order to have the Gautier family arrested... But what does this have to do with the Pyrrhus family?)",
  ui_story_5063_50631601_15_dialog_content = "(Could it be that the Chief Judge thinks the two families are colluding with one another?)",
  ui_story_5063_50631601_16_dialog_content = "(But that would mean Pam is...)",
  ui_story_5063_50631601_17_dialog_content = "Huh? Father!",
  ui_story_5063_50631601_18_dialog_content = "Pam...! Forget about me!",
  ui_story_5063_50631601_19_dialog_content = "<size=45>Run away, Pam! Run as fast as you can!!!</size>",
  ui_story_5063_50631601_20_dialog_content = "Why are they arresting my father, Lady Irridon?!",
  ui_story_5063_50631601_21_dialog_content = "We've done nothing but obey the law ever since we came to Lower Lumopolis, so why... Tell me, Lady Irridon!",
  ui_story_5063_50631601_22_dialog_content = "Could it be that this has something to do with your mission...?",
  ui_story_5063_50631601_23_dialog_content = "I can't tell you about my assignment, Pam. Not right now, at least... But I can assure you, it has nothing to do with this!",
  ui_story_5063_50631601_24_dialog_content = "For now, just listen to your father and run!",
  ui_story_5063_50631601_25_dialog_content = "<size=45>Now go!</size>",
  ui_story_5063_50631601_26_dialog_content = "Did a Pyrrhus family member get away over there?",
  ui_story_5063_50631601_27_dialog_content = "Set your suspicions aside, guards; that girl doesn't belong to the Pyrrhus family. She simply panicked at the sight and ran away.",
  ui_story_5063_50631601_28_dialog_content = "I see. Let's go search around there again!",
  ui_story_5063_50631601_29_dialog_content = "Pam...",
  ui_story_5063_50631601_30_dialog_content = "Heheh, so even Justice Knight is capable of telling lies, eh?",
  ui_story_5063_50631601_31_dialog_content = "It's you! I've been searching for you for some time now... How kind of you to turn yourself in to me!",
  ui_story_5063_50631601_32_dialog_content = "You, a Justice Knight of Lumopolis, let such a major criminal slip through your fingers...",
  ui_story_5063_50631601_33_dialog_content = "What crime do you think you've committed?",
  ui_story_5063_50631601_34_dialog_content = "As a Justice Knight, upholding the laws of Lumopolis isn't my only responsibility. I also have an obligation to protect the innocent people of this city!",
  ui_story_5063_50631601_35_dialog_content = "There must be some kind of misunderstanding! Why else would the Chief Judge apprehend the entire Pyrrhus family...?",
  ui_story_5063_50631601_36_dialog_content = "I'm going to explain everything to her the first chance I get, and clear Pam and her family of any wrongdoing!",
  ui_story_5063_50631601_37_dialog_content = "Oh? If that's the case, why are you so relentlessly hunting me down?",
  ui_story_5063_50631601_38_dialog_content = "Because you...",
  ui_story_5063_50631601_39_dialog_content = "Hm?",
  ui_story_5063_50631601_40_dialog_content = "You are...",
  ui_story_5063_50631601_41_dialog_content = "<size=45><color=#FFB400>Pam</color>?!</size>",
  ui_story_5063_50631601_42_dialog_content = "It's been ages since someone called me that name...",
  ui_story_5063_50631601_43_dialog_content = "But perhaps you know me better by one of the names on your most wanted list: <color=#FFB400>Paloma Pyrrhus</color>.",
  ui_story_5063_50631601_44_dialog_content = "You've been lying to me all this time...?",
  ui_story_5063_50631601_45_dialog_content = "Oh? Heheh, it seems you've forgotten after all...",
  ui_story_5063_50631601_46_dialog_content = "Are you willing to tell me what happened to you?",
  ui_story_5063_50631601_47_dialog_content = "You're the one who asked me to explain my circumstances to you.",
  ui_story_5063_50631601_48_dialog_content = "But just as I was about to do so, \"Pam\" suddenly broke away from my body.",
  ui_story_5063_50631601_49_dialog_content = "The person you know as Pam is me, but at the same time she isn't me...",
  ui_story_5063_50631601_50_dialog_content = "At this very moment, she should be hiding somewhere and experiencing the same pain I felt over a decade ago... Poor little thing.",
  ui_story_5063_50631601_51_dialog_content = "So when you forced your way into the Hall of Justice... It was to report this act of rebellion?",
  ui_story_5063_50631601_52_dialog_content = "I should've noticed it sooner...",
  ui_story_5063_50631601_53_dialog_content = "But there's still time! I'll just report my findings to the Chief Judge, and exonerate Pam... And you, as well!",
  ui_story_5063_50631601_54_dialog_content = "We'll just have to wait and see then, won't we?",
  ui_story_5063_50631601_55_dialog_content = "Justice Knight!",
  ui_story_5063_50631601_56_dialog_content = "The fugitive is right before your eyes. Why haven't you arrested her already?",
  ui_story_5063_50631601_57_dialog_content = "Before that, I would like to know what compelled you to authorize the arrests of the Gautier and Pyrrhus families.",
  ui_story_5063_50631601_58_dialog_content = "Isn't this all thanks to your investigation?",
  ui_story_5063_50631601_59_dialog_content = "But my investigation has already proven that most of the Pyrrhus family members are victims in this case, not perpetrators!",
  ui_story_5063_50631601_60_dialog_content = "Both the Gautier and Pyrrhus families were involved in prohibited experiments. Isn't that true?",
  ui_story_5063_50631601_61_dialog_content = "Yes, but they have already been punished for that crime. Moreover, you cannot hold every single person in their families accountable for that.",
  ui_story_5063_50631601_62_dialog_content = "Justice Knight! Do I really have to go through each one to see who turned into a monster willingly for treason and who didn't?",
  ui_story_5063_50631601_63_dialog_content = "To maintain Lumopolis' safety and stability, we can't afford to leave any potential risks.",
  ui_story_5063_50631601_64_dialog_content = "And what of the innocent people who had no part in those experiments?",
  ui_story_5063_50631601_65_dialog_content = "They didn't become monsters... They didn't do anything at all! So why must they bear the blame and lose their lives for it?",
  ui_story_5063_50631601_66_dialog_content = "Innocent? What a joke! The Pyrrhus family was guilty from the start. When the Hall of Justice sentenced them to exile in Lower Lumopolis, it was already a mercy.",
  ui_story_5063_50631601_67_dialog_content = "Now, they've even gotten involved in this treason case... Why should we go easy on a bunch of potential criminals from Lower Lumopolis?",
  ui_story_5063_50631601_68_dialog_content = "How can you determine whether or not a person deserves fair treatment under the law based solely on their status and residence?!",
  ui_story_5063_50631601_69_dialog_content = "I still believe your judgment is flawed, Chief Judge——",
  ui_story_5063_50631601_70_dialog_content = "This is a judgment your father would also make!",
  ui_story_5063_50631601_71_dialog_content = "Your father is a widely respected Chief Judge of Lumopolis. What, you're going against your own father now?",
  ui_story_5063_50631601_72_dialog_content = "I...",
  ui_story_5063_50631601_73_dialog_content = "Heheh.",
  ui_story_5063_50631601_74_dialog_content = "So you still have hope for Lumopolis and the Hall of Justice, I see?",
  ui_story_5063_50631601_75_dialog_content = "Don't let them keep brainwashing you!",
  ui_story_5063_50631601_76_dialog_content = "What are you doing?!",
  ui_story_5063_50631601_77_dialog_content = "I won't try to hurt you, but you'd better stay out of the way!",
  ui_story_5063_50631601_78_dialog_content = "It's time for me to eradicate the source of evil hiding behind you!",
  ui_story_5063_50631601_79_dialog_content = "Justice Knight! Take down this crazy woman now!",
  ui_story_5063_50631601_80_dialog_content = "...",
  ui_story_5063_50631601_81_dialog_content = "Stop, Paloma!",
  ui_story_5063_50631601_82_dialog_content = "Heheh... You really are no different than them.",
  ui_story_5063_50631601_83_dialog_content = "No, Paloma... I just refuse to watch you make an even greater mistake!",
  ui_story_5063_50631601_84_dialog_content = "You aren't the ones to decide what's right or wrong. There's no such thing as justice in Lumopolis!",
  ui_story_5063_50631601_85_dialog_content = "Killing someone won't bring you the justice you seek, either!",
  ui_story_5063_50631601_86_dialog_content = "If you don't deal with a problem at its source, it will never go away! You could destroy all of Lumopolis, and it still wouldn't stop the cycle of hatred and vengeance!",
  ui_story_5063_50631601_87_dialog_content = "In time, someone else would just create an even more arrogant and prejudiced Hall of Justice!",
  ui_story_5063_50631601_88_dialog_content = "Besides, are you really going to do this? Don't you resent the nobility for wiping everyone in their way all out?",
  ui_story_5063_50631601_89_dialog_content = "Are you trying to become like them?!",
  ui_story_5063_50631601_90_dialog_content = "I'm nothing like them!",
  ui_story_5063_50631601_91_dialog_content = "Then tell me, what's the difference between your actions right now and their own?",
  ui_story_5063_50631601_92_dialog_content = "...",
  ui_story_5063_50631601_93_dialog_content = "In that case... Do you have any better ideas?",
  ui_story_5063_50631601_94_dialog_content = "Perfect timing!",
  ui_story_5063_50631601_95_dialog_content = "Dismember!",
  ui_story_5063_50631601_96_dialog_content = "Urgh! Damn... I should've expected a sneak attack...",
  ui_story_5063_50631601_97_dialog_content = "Too bad for you... You underestimated me...",
  ui_story_5063_50631601_98_dialog_content = "*cough* Justice Knight... arrest... this crazy woman... *cough*",
  ui_story_5063_50631601_99_dialog_content = "I'll be at the Hall of Justice... awaiting your update...",
  ui_story_5063_50631601_100_dialog_content = "Hahaha! That's right, run with your tail... Between your legs...",
  ui_story_5063_50631601_101_dialog_content = "Paloma! A-Are you okay?",
  ui_story_5063_50631601_102_dialog_content = "Heheh, so you finally caught me. Now you can finally present your precious Chief Judge with something that'll make her happy.",
  ui_story_5063_50631601_103_dialog_content = "You're losing too much blood! Let me help!",
  ui_story_5063_50631601_104_dialog_content = "Hmph, you really don't have to keep pretending, you know. We're way past that now.",
  ui_story_5063_50631601_105_dialog_content = "Hey! Didn't you hear me? Stop wasting your time trying to treat my wounds!",
  ui_story_5063_50631601_106_dialog_content = "But I want to help! What else do you need me to do?",
  ui_story_5063_50631601_107_dialog_content = "Tch, I don't need anyone's help, so just give it up. All I need is a fair verdict... Think you can give me that?",
  ui_story_5063_50631601_108_dialog_content = "I... Of course I can!",
  ui_story_5063_50631601_109_dialog_content = "White Night up high! After an extensive investigation, the Hall of Justice concludes that Major Pyrrhus and his family harbored no rebellious intent. Furthermore, they were not involved in the Eclipsite experiments conducted by the Gautier family...",
  ui_story_5063_50631601_110_dialog_content = "As such, I hereby declare that they are all... Not guilty!",
  ui_story_5063_50631601_111_dialog_content = "...Not guilty, eh?",
  ui_story_5063_50631601_112_dialog_content = "Heh, I must be dreaming.",
  ui_story_5063_50631601_113_dialog_content = "Paloma? Wh-Where are you going?",
  ui_story_5063_50631601_114_dialog_content = "If I really am dreaming, then maybe it's time I finally wake up.",
  ui_story_5063_50631601_115_dialog_content = "As for you...",
  ui_story_5063_50631601_116_dialog_content = "I wonder if you'll ever do the same?",
  ui_story_5063_50631601_117_dialog_content = "Seriously... Why did you want to become a Justice Knight?",
  ui_story_5063_50631701_1_dialog_content = "What is this place? And... Where am I going?",
  ui_story_5063_50631701_2_dialog_content = "The Hall of Justice?",
  ui_story_5063_50631701_3_dialog_content = "Seriously... Why did you want to become a Justice Knight?",
  ui_story_5063_50631701_4_dialog_content = "I can't even remember the reason I wanted to work in the Hall of Justice in the first place...",
  ui_story_5063_50631701_5_dialog_content = "I've failed every single task given to me by the Chief Judge.",
  ui_story_5063_50631701_6_dialog_content = "And every verdict I've passed is the complete opposite of what my father decided.",
  ui_story_5063_50631701_7_dialog_content = "I say I want to change Lumopolis for the better, but... What can I truly accomplish on my own?",
  ui_story_5063_50631701_8_dialog_content = "<color=#e8d9bb>Buzz...</color>",
  ui_story_5063_50631701_9_dialog_content = "Huh? What was that?",
  ui_story_5063_50631701_10_dialog_content = "<color=#e8d9bb>Buzz...</color>",
  ui_story_5063_50631701_11_dialog_content = "Why did my magnifying glass fly out of my pocket? Wait, there's something strange on the lens...",
  ui_story_5063_50631701_12_dialog_content = "What? Th-There's a figure on the lens!",
  ui_story_5063_50631701_13_dialog_content = "Wait, that figure... Is that the Chief Judge?",
  ui_story_5063_50631701_14_dialog_content = "But something about the Chief Judge's face is different. It looks... Somewhat golden?",
  ui_story_5063_50631701_15_dialog_content = "Eh... You... You look...",
  ui_story_5063_50631701_16_dialog_content = "This is how you look now!",
  ui_story_5063_50631701_17_dialog_content = "Who are you...?",
  ui_story_5063_50631701_18_dialog_content = "I am your friend, PlayerName!",
  ui_story_5063_50631701_19_dialog_content = "But that doesn't matter. What matters is... you need to remember who you are!",
  ui_story_5063_50631701_20_dialog_content = "I... I am me. Irridon Novek, a Justice Knight of Lumopolis.",
  ui_story_5063_50631701_21_dialog_content = "Look into this mirror here! It shows your look!",
  ui_story_5063_50631701_22_dialog_content = "It's... my reflection? You must be joking! Why would I look just like the Chief Judge?",
  ui_story_5063_50631701_23_dialog_content = "Because you're actually the Chief Judge!",
  ui_story_5063_50631701_24_dialog_content = "I'm the real Chief Judge? Then who was that other woman from before?",
  ui_story_5063_50631701_25_dialog_content = "She... is also you, but only a part of you. She's the idealized version of yourself that you aspire to be in the real world...",
  ui_story_5063_50631701_26_dialog_content = "But she isn't really you! Because you've mixed too many other people's ideas into your own self-expectations.",
  ui_story_5063_50631701_27_dialog_content = "Get back your true self!",
  ui_story_5063_50631701_28_dialog_content = "<size=45>Wake up now!</size>",
  ui_story_5063_50631701_29_dialog_content = "...",
  ui_story_5063_50631701_30_dialog_content = "Why are you telling me to \"wake up\"?",
  ui_story_5063_50631701_31_dialog_content = "If I really am dreaming, then maybe it's time I finally wake up.",
  ui_story_5063_50631701_32_dialog_content = "As for you...",
  ui_story_5063_50631701_33_dialog_content = "I wonder if you'll ever do the same?",
  ui_story_5063_50631701_34_dialog_content = "Now that I think about it, everything I've experienced... Those people and their cases... Something did seem a bit strange about them.",
  ui_story_5063_50631701_35_dialog_content = "But if I truly am dreaming, then how am I supposed to wake up?",
  ui_story_5063_50631701_36_dialog_content = "...I need to find her. The other me.",
  ui_story_5063_50631801_1_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5063_50631801_2_dialog_content = "You? How did you get in here?",
  ui_story_5063_50631801_3_dialog_content = "The case involving the criminal known as Paloma has been settled. Tell me, Chief Judge, were you satisfied with my performance?",
  ui_story_5063_50631801_4_dialog_content = "You've been too indecisive. If it weren't for my intervention, you would have made an unforgivable mistake.",
  ui_story_5063_50631801_5_dialog_content = "If you had obeyed my commands right from the start, things would've been much smoother.",
  ui_story_5063_50631801_6_dialog_content = "\"Smoother\"? You mean replacing me, yes?",
  ui_story_5063_50631801_7_dialog_content = "So you're finally starting to remember...",
  ui_story_5063_50631801_8_dialog_content = "I see... Replacing me was your plan all along, wasn't it?",
  ui_story_5063_50631801_9_dialog_content = "Unfortunately, I won't let that happen, now or ever!",
  ui_story_5063_50631801_10_dialog_content = "It's useless to resist any further. I am the perfect daughter that father always wanted, not you.",
  ui_story_5063_50631801_11_dialog_content = "Only I am worthy of being the true Chief Judge of Lumopolis!",
  ui_story_5063_50631801_12_dialog_content = "You, on the other hand, have only succeeded in aiding and abetting evil! Father's sacrifice is wasted on the likes of you!",
  ui_story_5063_50631801_13_dialog_content = "Is that truly so? Thank you... I think I understand father a little better now.",
  ui_story_5063_50631801_14_dialog_content = "I realize now that I've always been eager to retry my father's old cases, to rectify his mistakes as well as those of the Hall of Justice...",
  ui_story_5063_50631801_15_dialog_content = "But what I wish to pass judgment on the most... Is not Paloma's revenge trial.",
  ui_story_5063_50631801_16_dialog_content = "But rather the arrogant and prejudiced traditions of Lumopolis!",
  ui_story_5063_50631801_17_dialog_content = "Do you even hear yourself right now? How could you claim that father's verdicts were wrong?!",
  ui_story_5063_50631801_18_dialog_content = "Father passed many reasonable judgments in his time, but even he made mistakes. Those mistakes led to wrongful verdicts, which in turn led to the deaths of innocent people!",
  ui_story_5063_50631801_19_dialog_content = "He should have been held accountable for his mistakes in a court of law, but his death put an end to any inquiries.",
  ui_story_5063_50631801_20_dialog_content = "But now, I finally know what prevented my father from making better decisions.",
  ui_story_5063_50631801_21_dialog_content = "A disease ran through his veins, one that has plagued all of Lumopolis throughout its long history...",
  ui_story_5063_50631801_22_dialog_content = "A disease that lurks deep in your subconscious, as well as mine!",
  ui_story_5063_50631801_23_dialog_content = "It's pride! Pride lies at the heart of Lumopolis' corruption, and by passing judgment on it, I will purge it from my very soul!",
  ui_story_5063_50631801_24_dialog_content = "You're merely defying your father out of resentment! You still fear him more than anything!",
  ui_story_5063_50631801_25_dialog_content = "I admit that I was too afraid to face him in the past.",
  ui_story_5063_50631801_26_dialog_content = "He may not have been a good father... But I know that he did his best for me.",
  ui_story_5063_50631801_27_dialog_content = "Which is why I can never forgive the traditions which imprisoned him for all of his life!",
  ui_story_5063_50631801_28_dialog_content = "If it wasn't for them, we could have been more like Pam and her father...",
  ui_story_5063_50631801_29_dialog_content = "Have you lost your mind? Are you truly envious of those criminals?!",
  ui_story_5063_50631801_30_dialog_content = "Do you still remember why you wanted to become Chief Judge?",
  ui_story_5063_50631801_31_dialog_content = "To succeed my father and inherit his legacy, of course!",
  ui_story_5063_50631801_32_dialog_content = "My reason is different. I became Chief Judge in order to protect Lumopolis and its people...",
  ui_story_5063_50631801_33_dialog_content = "Which is why I'll never let you have your way!",
  ui_story_5063_50631801_34_dialog_content = "Now leave, so that this city can finally be free of your malicious pride!",
  ui_story_5063_50631802_1_dialog_content = "No——",
  ui_story_5063_50631802_2_dialog_content = "I am father's ideal daughter, not you! How could I possibly lose to you?!",
  ui_story_5063_50631802_3_dialog_content = "Because your vision of an \"ideal daughter\" was created when I still didn't understand my father.",
  ui_story_5063_50631802_4_dialog_content = "By being harsh and merciless with others and myself, and by judging cases strictly in accordance with the law, I thought I could become the daughter my father always wanted.",
  ui_story_5063_50631802_5_dialog_content = "But I was wrong. After going over father's old cases, I discovered that despite his cold and aloof demeanor...",
  ui_story_5063_50631802_6_dialog_content = "Father strived to gather as much evidence as possible before going to trial, so that he could deliver the most just verdicts possible.",
  ui_story_5063_50631802_7_dialog_content = "However, his idea of \"justice\" was still tainted by the arrogance of outdated traditions.",
  ui_story_5063_50631802_8_dialog_content = "That would explain why everyone says that father was the best Chief Judge in Lumopolis' history, and that I'll never hold a candle to his greatness.",
  ui_story_5063_50631802_9_dialog_content = "...I never truly understood him or his way of thinking.",
  ui_story_5063_50631802_10_dialog_content = "But as judges, so long as we continue to do our best, the rule of law will eventually return to a state of balance.",
  ui_story_5063_50631802_11_dialog_content = "My father has given me two opportunities to live now. Though his sacrifice may not be enough to restore the balance between us...",
  ui_story_5063_50631802_12_dialog_content = "I'm willing to accept that.",
  ui_story_5063_50631802_13_dialog_content = "I will continue following in my father's footsteps, correcting his mistakes while striving to become a far greater Chief Judge than he ever was...",
  ui_story_5063_50631802_14_dialog_content = "With my life, I shall bring balance to the scales of justice!",
  ui_story_5063_50631802_15_dialog_content = "...",
  ui_story_5063_50631802_16_dialog_content = "I believe it's finally time to wake up.",
  ui_story_5063_50631802_17_dialog_content = "White Night up high! I hereby declare——",
  ui_story_5063_50631802_18_dialog_content = "<size=45>Court is adjourned!</size>"
}
return config
